/* Typed world/quest authoring controls shared by map and event editors. */
(function(){'use strict';const L=DecideWorldLinks,$=id=>document.getElementById(id),rows=()=>R.records(DB);function selectOptions(node,list,value){node.replaceChildren();for(const x of list)node.add(new Option(x.label,x.value));if(value&&!list.some(x=>x.value===value))node.add(new Option('ไม่พบเดิม: '+value,value));node.value=value||'';}
function control(root,label,value,change,{type='text',list,id}={}){const l=document.createElement('label');l.textContent=label;const input=document.createElement(list?'select':'input');if(id)input.id=id;input.setAttribute('aria-label',label);if(list)selectOptions(input,list,value);else{input.type=type;input.value=value??'';}input.onchange=()=>change(type==='number'?Number(input.value):input.value);l.append(input);root.append(l);return input;}
function itemOptions(){return [{value:'',label:'เลือกของจากฐานข้อมูล'},...rows().filter(r=>L.kinds.includes(r.kind)&&r.enabled!==false).map(r=>({value:r.kind+'/'+r.id,label:(r.displayName||r.name)+' · '+r.id}))];}
function conditions(root,owner,touch){owner.conditions??=[];root.replaceChildren();const legend=document.createElement('legend');legend.textContent='เงื่อนไข: ต้องครบทุกข้อ';root.append(legend);owner.conditions.forEach((c,i)=>{const box=document.createElement('div');box.className='world-condition';control(box,'ชนิดเงื่อนไข',c.type,value=>{const first=rows().find(r=>r.kind==='item'&&r.enabled!==false);owner.conditions[i]=value==='quest'?{type:value,id:'quest-id',status:'active'}:value==='item'?{type:value,kind:'item',id:first?.id||'item-id',quantity:1}:value==='skill'?{type:value,kind:'skill',id:rows().find(r=>r.kind==='skill'&&r.enabled!==false)?.id||'skill-id'}:value==='stat'?{type:value,stat:'CHA',minimum:10}:{type:value,key:'sword',grade:'D'};touch();conditions(root,owner,touch);},{list:[{value:'quest',label:'สถานะเควส'},{value:'item',label:'มีของอย่างน้อย'},{value:'skill',label:'รู้สกิล/เวท'},{value:'stat',label:'ค่าสถานะขั้นต่ำ'},{value:'proficiency',label:'ระดับความชำนาญ'}]});const update=(k,v)=>{c[k]=v;touch();};if(c.type==='quest'){control(box,'ID เควส',c.id,v=>update('id',v));control(box,'ต้องเป็นสถานะ',c.status,v=>update('status',v),{list:[{value:'absent',label:'ยังไม่รับ'},{value:'active',label:'กำลังทำ'},{value:'ready',label:'ครบเป้าหมาย พร้อมส่ง'},{value:'completed',label:'สำเร็จ'},{value:'failed',label:'ล้มเหลว'}]});}if(c.type==='item'){control(box,'ของที่ต้องมี',c.kind+'/'+c.id,v=>{if(!v)return;[c.kind,c.id]=v.split('/');touch();},{list:itemOptions()});control(box,'จำนวนขั้นต่ำ',c.quantity,v=>update('quantity',v),{type:'number'});}if(c.type==='skill')control(box,'วิชาที่ต้องรู้',c.kind+'/'+c.id,v=>{[c.kind,c.id]=v.split('/');touch();},{list:rows().filter(r=>['skill','spell'].includes(r.kind)&&r.enabled!==false).map(r=>({value:r.kind+'/'+r.id,label:r.name+' · '+r.id}))});if(c.type==='stat'){control(box,'ค่าสถานะ',c.stat,v=>update('stat',v),{list:DecideCreation.stats.map(v=>({value:v,label:v}))});control(box,'ขั้นต่ำ',c.minimum,v=>update('minimum',v),{type:'number'});}if(c.type==='proficiency'){control(box,'ความชำนาญ',c.key,v=>update('key',v),{list:Object.entries({...DecideCreation.profs,dual:'Dual Wield'}).map(([value,label])=>({value,label}))});control(box,'ระดับขั้นต่ำ',c.grade,v=>update('grade',v),{list:['D','C','B','A','S'].map(value=>({value,label:value}))});}const remove=document.createElement('button');remove.textContent='ลบเงื่อนไข';remove.onclick=()=>{owner.conditions.splice(i,1);touch();conditions(root,owner,touch);};box.append(remove);root.append(box);});const add=document.createElement('button');add.textContent='เพิ่มเงื่อนไข';add.disabled=owner.conditions.length>=12;add.onclick=()=>{owner.conditions.push({type:'quest',id:'quest-id',status:'active'});touch();conditions(root,owner,touch);};root.append(add);}
function outcomes(root,ch,touch){ch.consumeItems??=[];const box=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent='ส่งของ / รางวัลครั้งเดียว / NPC';box.append(legend);for(let i=0;i<ch.consumeItems.length;i++){const ref=ch.consumeItems[i],line=document.createElement('div');line.className='world-condition';control(line,'ของที่ต้องส่ง (หักจากกระเป๋า/คลัง)',ref.kind+'/'+ref.id,v=>{if(!v)return;[ref.kind,ref.id]=v.split('/');touch();},{list:itemOptions()});control(line,'จำนวนที่ส่ง',ref.quantity,v=>{ref.quantity=v;touch();},{type:'number'});const remove=document.createElement('button');remove.textContent='ลบของส่ง';remove.onclick=()=>{ch.consumeItems.splice(i,1);touch();box.remove();outcomes(root,ch,touch);};line.append(remove);box.append(line);}const add=document.createElement('button');add.textContent='เพิ่มของที่ต้องส่ง';add.disabled=ch.consumeItems.length>=12;add.onclick=()=>{const r=rows().find(r=>r.kind==='item'&&r.enabled!==false);ch.consumeItems.push({kind:r.kind,id:r.id,quantity:1});touch();box.remove();outcomes(root,ch,touch);};box.append(add);control(box,'รหัสรับผลครั้งเดียว (ไม่บังคับ; เควสสำเร็จกันซ้ำให้อัตโนมัติ)',ch.onceKey||'',v=>{ch.onceKey=v;touch();});control(box,'การกระทำกับ NPC',ch.npcAction?.type||'',v=>{ch.npcAction=v?{type:v,npcId:ch.npcAction?.npcId||rows().find(r=>r.kind==='npc'&&r.enabled!==false)?.id}:null;touch();box.remove();outcomes(root,ch,touch);},{list:[{value:'',label:'ไม่มี'},{value:'shop',label:'เปิดร้าน ซื้อ/ขาย แล้วกลับมาคุย'},{value:'craft',label:'เปิดปรุงยา แล้วกลับมาคุย'},{value:'recruit',label:'ชวน NPC เข้าทีม'},{value:'dismiss',label:'ให้ NPC ออกจากทีม'}]});if(ch.npcAction)control(box,'NPC ของการกระทำ',ch.npcAction.npcId,v=>{ch.npcAction.npcId=v;touch();},{list:rows().filter(r=>r.kind==='npc'&&r.enabled!==false).map(r=>({value:r.id,label:r.name+' · '+r.id}))});const hint=document.createElement('small');hint.textContent='เปิดร้าน/ปรุงยาใช้ตัวเลือกแยก ไม่มีรางวัลหรือบทปลายทางในข้อเดียวกัน เมื่อปิดบริการจะกลับบทเดิม • ส่งของและรางวัลทำพร้อมกันเมื่อเงื่อนไขผ่าน';box.append(hint);root.append(box);}
function objectives(root,quest,touch){quest.objectives??=[];const box=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent='เป้าหมายเควส (ตรวจครบก่อนส่ง)';box.append(legend);for(let i=0;i<quest.objectives.length;i++){const o=quest.objectives[i],line=document.createElement('div');line.className='world-condition';control(line,'ชนิดเป้าหมาย',o.type,v=>{quest.objectives[i]=v==='kill'?{type:'kill',monsterId:rows().find(r=>r.kind==='monster'&&r.enabled!==false)?.id,required:1}:{type:'item',kind:'item',id:rows().find(r=>r.kind==='item'&&r.enabled!==false)?.id,required:1};touch();box.remove();objectives(root,quest,touch);},{list:[{value:'kill',label:'ปราบมอนสเตอร์เมื่อชนะไฟต์'},{value:'item',label:'มีของครบจำนวน'}]});if(o.type==='kill')control(line,'มอนสเตอร์เป้าหมาย',o.monsterId,v=>{o.monsterId=v;touch();},{list:rows().filter(r=>r.kind==='monster'&&r.enabled!==false).map(r=>({value:r.id,label:r.name+' · '+r.id}))});else control(line,'ของเป้าหมาย',o.kind+'/'+o.id,v=>{if(!v)return;[o.kind,o.id]=v.split('/');touch();},{list:itemOptions()});control(line,'จำนวนเป้าหมายที่ต้องครบ',o.required,v=>{o.required=v;touch();},{type:'number'});const remove=document.createElement('button');remove.textContent='ลบเป้าหมาย';remove.onclick=()=>{quest.objectives.splice(i,1);touch();box.remove();objectives(root,quest,touch);};line.append(remove);box.append(line);}const add=document.createElement('button');add.textContent='เพิ่มเป้าหมายเควส';add.disabled=quest.objectives.length>=8;add.onclick=()=>{quest.objectives.push({type:'kill',monsterId:rows().find(r=>r.kind==='monster'&&r.enabled!==false)?.id,required:1});touch();box.remove();objectives(root,quest,touch);};box.append(add);root.append(box);}
const article=document.createElement('article');article.id='worldLinksEditor';article.innerHTML='<h2>NPC และจุดเชื่อมโลก</h2><label class="check"><input id="worldEnforceLocations" type="checkbox">ใช้ตำแหน่งจริงกับ NPC/บริการ/กิจกรรม/บทตัวอย่าง</label><p>ข้อมูลเก่าปิดไว้จนพร้อมกำหนดจุด เมื่อเพิ่ม NPC ครั้งแรกจะเปิดให้ ตรวจสถานที่ของบทตัวอย่างด้านล่างด้วย</p><div id="chapterPlacesEditor"></div><h3>วาง NPC</h3><label>NPC<select id="worldNpcSelect"></select></label><label>สถานที่<select id="worldNpcPlace"></select></label><label>บทสนทนา<select id="worldNpcEvent"></select></label><label class="check"><input id="worldNpcDialogueOnly" type="checkbox" checked>ใช้ร้าน/รับเพื่อนผ่านบทสนทนาเท่านั้น (เมื่อมีบท)</label><button id="worldNpcAdd">บันทึกตำแหน่ง NPC ลงฉบับแก้ไข</button><div id="worldNpcList"></div><p id="worldLinksStatus" role="status"></p>';$('mapEditorScreen').querySelector('aside').append(article);
const draft=()=>EvervaleMaps.editConfig(),touch=()=>{EvervaleMaps.touch();$('worldLinksStatus').textContent='มีการแก้ไข NPC/จุดเชื่อม • กดบันทึกแผนที่และซิงก์';},pointOptions=c=>c.maps.flatMap(m=>m.locations.map(p=>({value:m.id+'/'+p.id,label:m.name+' · '+p.name+' ('+m.id+'/'+p.id+')'}))),split=v=>{const [mapId,placeId]=v.split('/');return {mapId,placeId};},ensure=c=>c.worldRules??={enforceLocations:false,chapterPlaces:{village:null,forest:null,cave:null}};
function renderMap(){const c=draft();if(!c)return;$('worldEnforceLocations').checked=!!c.worldRules?.enforceLocations;const points=pointOptions(c);$('chapterPlacesEditor').replaceChildren();for(const [key,label]of [['village','บทตัวอย่าง: หมู่บ้าน'],['forest','บทตัวอย่าง: ป่า'],['cave','บทตัวอย่าง: ถ้ำ']])control($('chapterPlacesEditor'),label,c.worldRules?.chapterPlaces?.[key]?DecideWorldTravel.key(c.worldRules.chapterPlaces[key]):'',v=>{ensure(c).chapterPlaces??={};c.worldRules.chapterPlaces[key]=v?split(v):null;touch();},{id:'chapterPlace-'+key,list:[{value:'',label:'ยังไม่ผูกสถานที่'},...points]});selectOptions($('worldNpcSelect'),rows().filter(r=>r.kind==='npc'&&r.enabled!==false).map(r=>({value:r.id,label:r.name+' · '+r.id})),$('worldNpcSelect').value||rows().find(r=>r.kind==='npc')?.id);selectOptions($('worldNpcPlace'),points,$('worldNpcPlace').value||points[0]?.value);selectOptions($('worldNpcEvent'),[{value:'',label:'ไม่มีบท (บริการตรง)'},...(c.events||[]).map(e=>({value:e.id,label:e.id+' · '+e.name+(e.enabled?'':' (พักไว้)')}))],$('worldNpcEvent').value);const root=$('worldNpcList');root.replaceChildren();for(const p of c.npcPlacements||[]){const line=document.createElement('p');line.textContent=(rows().find(r=>r.kind==='npc'&&r.id===p.npcId)?.name||p.npcId)+' · '+p.mapId+'/'+p.placeId+' · '+(p.eventId||'บริการตรง')+(p.enabled?'':' (พักไว้)')+' ';const remove=document.createElement('button');remove.textContent='ลบตำแหน่ง';remove.onclick=()=>{c.npcPlacements=c.npcPlacements.filter(x=>x!==p);touch();renderMap();};line.append(remove);root.append(line);}}
$('worldEnforceLocations').onchange=()=>{ensure(draft()).enforceLocations=$('worldEnforceLocations').checked;touch();};$('worldNpcAdd').onclick=()=>{try{const c=draft(),npcId=$('worldNpcSelect').value,p=split($('worldNpcPlace').value),eventId=$('worldNpcEvent').value;c.npcPlacements??=[];const old=c.npcPlacements.find(x=>x.npcId===npcId&&x.mapId===p.mapId&&x.placeId===p.placeId),value={npcId,...p,eventId,dialogueOnly:!!eventId&&$('worldNpcDialogueOnly').checked,enabled:true};if(old)Object.assign(old,value);else c.npcPlacements.push(value);if(!c.worldRules)c.worldRules={enforceLocations:true,chapterPlaces:{village:null,forest:null,cave:null}};touch();renderMap();}catch(e){$('worldLinksStatus').textContent=e.message;}};
window.DecideWorldLinksEditor={conditions,outcomes,objectives,renderMap};
})();
